    async def screenshot(self, request: WireModel | Mapping[str, Any]) -> bytes | AsyncBulkLease:
        request_wire = _params(request)
        result = ScreenshotResultV1.from_dict(await self._call("view.screenshot", request_wire))
        mime = {"png": "image/png", "jpeg": "image/jpeg", "webp": "image/webp"}.get(request_wire.get("format"))
        expected_width = math.floor(float(request_wire.get("width", 0)) * float(request_wire.get("pixelRatio", 0)) + 0.5)
        expected_height = math.floor(float(request_wire.get("height", 0)) * float(request_wire.get("pixelRatio", 0)) + 0.5)
        if result.request_id != request_wire.get("requestId") or result.mime_type != mime or result.width != expected_width or result.height != expected_height:
            raise ProtocolError(raw_code="invalidRequest", message="screenshot result does not match request correlation or dimensions")
        if result.encoding == "base64" and result.data is not None:
            return base64.b64decode(result.data, validate=True)
        if result.encoding == "bulkLease" and result.lease is not None:
            return AsyncBulkLease(self, result.lease)
        raise ProtocolError(raw_code="invalidRequest", message="screenshot result lacks data for its encoding")

