    async def _app(self, method: str, params: Mapping[str, Any], expected: str, *, extensions: Mapping[str, Any] | None = None) -> Any:
        self._require(APP_METHOD_CAPABILITIES[method])
        request_id = str(uuid.uuid4())
        envelope = {"schemaId": "hcad.app-protocol@1", "requestId": request_id, "request": {"method": method, "params": params}}
        if extensions is not None: envelope["extensions"] = dict(extensions)
        return _app_payload(await self.transport.request("app.protocol", envelope), expected, request_id)

    async def _call(self, method: str, params: Mapping[str, Any]) -> Mapping[str, Any]:
        capability = METHOD_CAPABILITIES.get(method)
        if capability is not None: self._require(capability)
        response = await self.transport.request(method, params)
        _raise_direct_error(response)
        return response

    def _require(self, capability: str) -> None:
        if self.session is None or capability not in self.session.capabilities:
            raise ProtocolError(raw_code="missingCapability", message=f"negotiated session lacks {capability}")
